      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n수도권 거주자 / 18세-35세 남성) 구글관련 커뮤니티 활동인원을 모집합니다.\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.03. 16:23\n조회 55\n구독\n수도권 거주자 / 18세-35세 남/여) 구글관련 커뮤니티 활동인원을 모집합니다.\n**수도권 거주자 / 18세-35세 남/여\n**활동기간이 6개월이니 책임감을 가지고 성실하게 활동 할 수 있는 분들 소개 부탁드립니다.\n**진행 절차는 아래와 같습니다\n모집 신청 후 대상 조건이 맞는지 스크리너 작성 후 -> 조건 확인하여 담당자가 스크리너 입력 -> 플랫폼 가입관련 안내메일 수신 ->플랫폼 가입(구글 메일계정 필요/선착순)\n**플랫폼 가입시 비밀번호는 반드시 기억하거나 메모 해두세요.\n가입 후 활동에 대한 부분은 구글 담당자(플랫폼 가입시 담당자 메일 확인)에게 문의하며 진행하시면 되며\n본인이 구글 재미나이 앱 (구글 액티비티)에서 주1회~2회 활동해야 합니다.\n기본 활동 기간은 6개월이며, 기본적인 활동외에\n추가 활동이 있을경우 사전 안내가 나가며, 추가활동에 대한 부분은 선택사항입니다.\n**주간활동 및 인센티브 지급\n1. 사용기기 : 스마트폰\n2. 최소 활동 횟수 : 주 1회\n3. 활동시간 : 1회당 약 5분~10분\n4. 인센티브 : 1회당 10000원(쿠폰으로 지급)\n5. 지급시기 : 전 주 활동 내역을 기준으로 다음주 지급\n신청시 아래 부분을 작성하여 신청 부탁드립니다.\n1.이름/성별/나이/전화번호\n2.거주지역\n3.직업\n4.메일주소(스크리너 작성파일을 메일로 전달)\nhttps://forms.gle/S3w7cfUBuS47pK1AA\n수도권 거주자 / 18세-35세 남/여) 구글관련 커뮤니티 활동인원을 모집합니다.\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n0\n송파구의 더 많은 인기글 보러가기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.03. 19:31 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n수도권 거주자 / 18세-35세 여성) 구글관련 커뮤니티 활동인원을 모집합니다.\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n수도권 거주자 / 18세-35세 남성) 구글관련 커뮤니티 활동인원을 모집합니다.\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n급급급) 만 18–35세 성인 여성 ) AI 평가단 100명 모집\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n급급급) 만 18–35세 성인 남성 ) AI 평가단 100명 모집\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
