      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n9/17~21) 프리미엄 빌트인 가전 구매의향자 조사\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.03. 17:42\n조회 73\n구독\n9/17~21) 프리미엄 빌트인 가전 조사\n<신청링크>\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://kon.kric.com/project/2608014_C/INDEX.asp\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n마지막 소개자 문항에 꼭 소개자명 기재 부탁드립니다.\n<대상자조건>\n1.구매자\n- 최근 1년 내 프리미엄 빌트인 가전을 설치하신 분\n★대상브랜드: SKS(스위트 키친 스위트), 밀레, 가게나우, 데이코, 서브제로&울프, 리페르, 디트리쉬, 라코르뉴, 오피치네 굴로, 라칸슈, 아가, 보쉬\n- 가전 및 설치 전경 사진 제출 필수\n- SKS서울투어(강남구 소재) 방문 필요\n2. 구매의향자\n- 향후 6개월 내 프리미엄 빌트인 가전 설치 의향이 있는분\n★대상브랜드: SKS(스위트 키친 스위트), 밀레, 가게나우, 데이코, 서브제로&울프, 리페르, 디트리쉬, 라코르뉴, 오피치네 굴로, 라칸슈, 아가, 보쉬\n- 견적서, 매장 방문 인증샷 등 증빙 제출 필수\n- SKS서울투어(강남구 소재) 방문 필요\n<진행방법 및 일정>\n- 좌담회, 약 2시간 소요, 서울 서초구 소재 코리아리서치에서 진행\n- 일정: 9/17(목)~21(월) 중 진행(개별안내)\n<사례비>\n- 구매자: 세전 50만원(기타소득세 제외 약 45만원 이체)\n- 구매의향자: 세전 20만원(기타소득세 제외 약 18만원 이체)\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.03. 19:27 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n10/9~10) 만 30세~64세 남여) 준중형/중형 보유자이면서 향후 2년내 준대형 구매 의향자\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n9/17~21) 프리미엄 빌트인 가전 구매의향자 조사\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n9/17~21) 프리미엄 빌트인 가전 구매자 조사\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n9월~추석 전)빅5병원 입원수술예정 환자&보호자-삼성서울병원(일원), 서울성모병원(서초), 서울아산병원(풍납), 서울대학교병원, 연세세브란스병원\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
