      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n9/9~10) (긴급/일정촉박) 아동&보호자 관련 설문조사 -만9세 ~ 만17세 사이의 자녀가 있는 가구 (2008.09.01~2017.08.31 출생자녀)\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.09.03. 18:26\n조회 106\n구독\n9/9~10) (긴급/일정촉박) 아동&보호자 관련 설문조사 -만9세 ~ 만17세 사이의 자녀가 있는 가구 (2008.09.01~2017.08.31 출생자녀)\n수도권에 거주하는 분들 대상으로 아동&보호자 관련 설문조사가 진행되어 신청 부탁드립니다.\n현장에서 설문지 1부 풀어보시고 질문지에 대한 의견을 말하는 간단한 좌담회입니다.\n● 좌담회 일정 : 9/9(수), 9/10(목) 오후 7시\n*신청자분들의 선호시간에 따라 시간은 바뀔 수 있습니다.\n*보호자와 자녀용 설문지가 따로 있기 때문에 반드시 같이 오셔야 하는 좌담회 입니다. (보호자만 오거나 자녀만 올 수 없음)\n● 대상 및 조건 :\n1) 만9세 ~ 만17세 사이의 자녀가 있는 가구 (2008.09.01~2017.08.31 출생자녀)\n2) 보호자와 자녀가 함께 오실 수 있는 분.\n● 좌담회 방법 : 대면 좌담회(서울 서초구 교대역 인근에서 진행)\n● 좌담회 시간 : 최대 2시간\n● 사례비 : 보호자&아동 각 6만원 (한 가구기준 12만원)\n● 회신내용 :\n보호자 : 이름 / 연락처 / 성별 / 나이 / 거주지(사는 동까지만) / 직업\n자녀 : 이름 / 성별 / 생년월일\nhttps://forms.gle/CGzYHGMkwp3hscEaA\n9/9~10) (긴급/일정촉박) 아동&보호자 관련 설문조사 -만9세 ~ 만17세 사이의 자녀가 있는 가구 (2008.09.01~2017.08.31 출생자녀)\n010-4648-7146 -- 연락처 사이 하이픈 꼭 챙겨주시구요^^ 하이픈 안챙기시는 분 연락처에 숫자가 한개씩 누락되어서 숫자10개가 옵니다ㅠㅠ 연락처 적으신 후 숫자 11개 모두 적었는지 확인 부탁드립니다^^ 간혹 남의번호 적는분이 계십니다,그사람 아닌데요 하면,굉장히 민망하지요ㅠ 적고나서 확인부탁드립니다~ 해당없는 칸에는 해당없음 또는 점 . 또는 무 로 적어주세요~\nforms.gle\n좋아요\n1\n좋아요한 사람 목록으로 이동\n송파구 이웃끼리 공유하는 동네 꿀정보\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.09.03. 19:26 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n만 25~40세 미혼여성) 50분 5만) 피부 미용 관련 온라인 줌 조사\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n9/9~10) (긴급/일정촉박) 아동&보호자 관련 설문조사 -만9세 ~ 만17세 사이의 자녀가 있는 가구 (2008.09.01~2017.08.31 출생자녀)\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n9/29~10/2) 20-54세 남녀) 맥주 맛테스트\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n9/16) 자동차 조사 좌담회 -여성\n좌담회알바좌담회카페\n26.09.03.\n댓글\n1\n5페이지중 1페이지 버튼\n5페이지중 2페이지 버튼\n5페이지중 3페이지 버튼\n5페이지중 4페이지 버튼\n5페이지중 5페이지 버튼\n좌담회알바좌담회카페\n 님\n의 글을 3개 보셨네요. 👀\n구독하고 새로운 글을 놓치지 마세요!\n멤버 구독하기\n목록으로\n좋아요\n1\n좋아요한 사람 목록으로 이동\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
